def make(n):
    m = min(n, 8)
    args = []
    for i in range(1, m + 1):
        args.append([i])
    return args

def make(n):
    bases = [{}, {}]
    for _ in range(n - 2):
        bases.append({
            "key": string.ascii_lowercase[random.randint(0, 25)],
            "val": random.randint(0, 100),
            "flag": random.choice([True, False]),
        })
    return bases

def make(n):
    limits = [1, 2, 4, 8]
    k = min(n, len(limits))
    return list(itertools.islice(itertools.combinations(limits, r) for r in range(1, k + 1), 0, 1))
